// Generates src/bindings/index.ts re-exporting every ts-rs generated type.
// Run after `cargo test -p openmeet-core` (see `npm run bindings`).
import { readdirSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const dir = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "bindings");
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .sort();

const lines = [
  "// Generated by scripts/gen-bindings-index.mjs. Do not edit.",
  ...files.map((f) => {
    const name = f.replace(/\.ts$/, "");
    return `export type { ${name} } from "./${name}";`;
  }),
  "",
];
writeFileSync(join(dir, "index.ts"), lines.join("\n"));
console.log(`bindings index: ${files.length} types`);
